    @Test fun testGetQuery() {
        var target = ParentChildrenSyncDownTarget(ParentInfo("Parent", "parentsSoup", "ParentId", "ParentModifiedDate"), listOf("ParentName", "Title"), "School = 'MIT'", ChildrenInfo("Child", "Children", "childrenSoup", "parentId", "ChildId", "ChildLastModifiedDate"), listOf("ChildName", "School"), RelationshipType.LOOKUP)
        Assert.assertEquals("select ParentName, Title, ParentId, ParentModifiedDate, (select ChildName, School, ChildId, ChildLastModifiedDate from Children) from Parent where School = 'MIT' order by ParentModifiedDate", target.getQuery())
        target = ParentChildrenSyncDownTarget(ParentInfo("Parent", "parentsSoup"), listOf("ParentName", "Title"), "School = 'MIT'", ChildrenInfo("Child", "Children", "childrenSoup", "parentId"), listOf("ChildName", "School"), RelationshipType.LOOKUP)
        Assert.assertEquals("select ParentName, Title, Id, LastModifiedDate, (select ChildName, School, Id, LastModifiedDate from Children) from Parent where School = 'MIT' order by LastModifiedDate", target.getQuery())
    }

    @Test fun testGetQueryWithMaxTimeStamp() {
        val date = Date(); val dateStr = Constants.TIMESTAMP_FORMAT.format(date); val dateLong = date.time
        var target = ParentChildrenSyncDownTarget(ParentInfo("Parent", "parentsSoup", "ParentId", "ParentModifiedDate"), listOf("ParentName", "Title"), "School = 'MIT'", ChildrenInfo("Child", "Children", "childrenSoup", "parentId", "ChildId", "ChildLastModifiedDate"), listOf("ChildName", "School"), RelationshipType.LOOKUP)
        Assert.assertEquals("select ParentName, Title, ParentId, ParentModifiedDate, (select ChildName, School, ChildId, ChildLastModifiedDate from Children where ChildLastModifiedDate > $dateStr) from Parent where ParentModifiedDate > $dateStr and School = 'MIT' order by ParentModifiedDate", target.getQuery(dateLong))
        target = ParentChildrenSyncDownTarget(ParentInfo("Parent", "parentsSoup"), listOf("ParentName", "Title"), "School = 'MIT'", ChildrenInfo("Child", "Children", "childrenSoup", "parentId"), listOf("ChildName", "School"), RelationshipType.LOOKUP)
        Assert.assertEquals("select ParentName, Title, Id, LastModifiedDate, (select ChildName, School, Id, LastModifiedDate from Children where LastModifiedDate > $dateStr) from Parent where LastModifiedDate > $dateStr and School = 'MIT' order by LastModifiedDate", target.getQuery(dateLong))
    }

    @Test fun testGetSoqlForRemoteIds() {
        var target = ParentChildrenSyncDownTarget(ParentInfo("Parent", "parentsSoup", "ParentId", "ParentModifiedDate"), listOf("ParentName", "Title"), "School = 'MIT'", ChildrenInfo("Child", "Children", "childrenSoup", "ChildParentId", "ChildId", "ChildLastModifiedDate"), listOf("ChildName", "School"), RelationshipType.LOOKUP)
        Assert.assertEquals("select ParentId from Parent where School = 'MIT'", target.soqlForRemoteIds)
        target = ParentChildrenSyncDownTarget(ParentInfo("Parent", "parentsSoup"), listOf("ParentName", "Title"), "School = 'MIT'", ChildrenInfo("Child", "Children", "childrenSoup", "ChildParentId"), listOf("ChildName", "School"), RelationshipType.LOOKUP)
        Assert.assertEquals("select Id from Parent where School = 'MIT'", target.soqlForRemoteIds)
    }

    @Test fun testGetDirtyRecordIdsSql() {
        val target = ParentChildrenSyncDownTarget(ParentInfo("Parent", "parentsSoup", "ParentId", "ParentModifiedDate"), listOf("ParentName", "Title"), "School = 'MIT'", ChildrenInfo("Child", "Children", "childrenSoup", "ChildParentId", "ChildId", "ChildLastModifiedDate"), listOf("ChildName", "School"), RelationshipType.LOOKUP)
        Assert.assertEquals("SELECT DISTINCT {parentsSoup:IdForQuery} FROM {parentsSoup} WHERE {parentsSoup:__local__} = 'true' OR EXISTS (SELECT {childrenSoup:ChildId} FROM {childrenSoup} WHERE {childrenSoup:ChildParentId} = {parentsSoup:ParentId} AND {childrenSoup:__local__} = 'true')", target.getDirtyRecordIdsSql("parentsSoup", "IdForQuery"))
    }

    @Test fun testGetNonDirtyRecordIdsSql() {
        val target = ParentChildrenSyncDownTarget(ParentInfo("Parent", "parentsSoup", "ParentId", "ParentModifiedDate"), listOf("ParentName", "Title"), "School = 'MIT'", ChildrenInfo("Child", "Children", "childrenSoup", "ChildParentId", "ChildId", "ChildLastModifiedDate"), listOf("ChildName", "School"), RelationshipType.LOOKUP)
        Assert.assertEquals("SELECT DISTINCT {parentsSoup:IdForQuery} FROM {parentsSoup} WHERE {parentsSoup:__local__} = 'false' AND {parentsSoup:__sync_id__} = 123 AND NOT EXISTS (SELECT {childrenSoup:ChildId} FROM {childrenSoup} WHERE {childrenSoup:ChildParentId} = {parentsSoup:ParentId} AND {childrenSoup:__local__} = 'true')", ParentChildrenSyncTargetHelper.getNonDirtyRecordIdsSql(ParentInfo("Parent", "parentsSoup", "ParentId", "ParentModifiedDate"), ChildrenInfo("Child", "Children", "childrenSoup", "ChildParentId", "ChildId", "ChildLastModifiedDate"), "IdForQuery", "AND {parentsSoup:__sync_id__} = 123"))
    }

    @Test fun testGetDirtyAndNonDirtyRecordIds() { val accountNames = arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)); val mapAccountToContacts = createAccountsAndContactsLocally(accountNames, 3); val accounts = mapAccountToContacts.keys.toTypedArray(); tryGetDirtyRecordIds(accounts); tryGetNonDirtyRecordIds(arrayOf()); cleanRecord(ACCOUNTS_SOUP, accounts[1]); cleanRecords(CONTACTS_SOUP, mapAccountToContacts[accounts[2]]!!); cleanRecord(ACCOUNTS_SOUP, accounts[3]); cleanRecords(CONTACTS_SOUP, mapAccountToContacts[accounts[3]]!!); cleanRecord(CONTACTS_SOUP, mapAccountToContacts[accounts[4]]!![0]); cleanRecord(ACCOUNTS_SOUP, accounts[5]); cleanRecord(CONTACTS_SOUP, mapAccountToContacts[accounts[5]]!![0]); tryGetDirtyRecordIds(arrayOf(accounts[0], accounts[1], accounts[2], accounts[4], accounts[5])); tryGetNonDirtyRecordIds(arrayOf(accounts[3])) }

    @Test fun testSaveRecordsToLocalStore() { val numberAccounts = 4; val numberContactsPerAccount = 3; val syncId = 123L; val accountAttributes = JSONObject(); accountAttributes.put(TYPE, Constants.ACCOUNT); val contactAttributes = JSONObject(); contactAttributes.put(TYPE, Constants.CONTACT); val accounts = Array(numberAccounts) { JSONObject() }; val mapAccountContacts = HashMap<JSONObject, Array<JSONObject>>(); for (i in 0 until numberAccounts) { val account = JSONObject(); account.put(Constants.ID, SyncTarget.createLocalId()); account.put(Constants.ATTRIBUTES, accountAttributes); val contacts = Array(numberContactsPerAccount) { j -> JSONObject().apply { put(Constants.ID, SyncTarget.createLocalId()); put(Constants.ATTRIBUTES, contactAttributes); put(ACCOUNT_ID, account.get(Constants.ID)) } }; mapAccountContacts[account] = contacts; accounts[i] = account }; val records = JSONArray(); for (account in accounts) { val record = JSONObject(account.toString()); val contacts = JSONArray(); for (contact in mapAccountContacts[account]!!) { contacts.put(contact) }; record.put("Contacts", contacts); records.put(record) }; val target = getAccountContactsSyncDownTarget(); target.saveRecordsToLocalStore(syncManager, ACCOUNTS_SOUP, records, syncId); val accountsFromDb = queryWithInClause(ACCOUNTS_SOUP, Constants.ID, JSONObjectHelper.pluck<String>(accounts, Constants.ID).toTypedArray(), null); Assert.assertEquals("Wrong number of accounts in db", accounts.size, accountsFromDb.size); for (i in accountsFromDb.indices) { val account = accounts[i]; val accountFromDb = accountsFromDb[i]; Assert.assertEquals(account.getString(Constants.ID), accountFromDb.getString(Constants.ID)); Assert.assertEquals(false, accountFromDb.getBoolean(SyncTarget.LOCAL)); Assert.assertEquals(syncId, accountFromDb.getLong(SyncTarget.SYNC_ID)); val contactsFromDb = queryWithInClause(CONTACTS_SOUP, ACCOUNT_ID, arrayOf(account.getString(Constants.ID)), SmartStore.SOUP_ENTRY_ID); val contacts = mapAccountContacts[account]!!; Assert.assertEquals("Wrong number of contacts in db", contacts.size, contactsFromDb.size); for (j in contactsFromDb.indices) { val contact = contacts[j]; val contactFromDb = contactsFromDb[j]; Assert.assertEquals(contact.getString(Constants.ID), contactFromDb.getString(Constants.ID)); Assert.assertEquals(false, contactFromDb.getBoolean(SyncTarget.LOCAL)); Assert.assertEquals(syncId, contactFromDb.getLong(SyncTarget.SYNC_ID)); Assert.assertEquals(accountFromDb.getString(Constants.ID), contactFromDb.getString(ACCOUNT_ID)) } } }

    @Test fun testGetLatestModificationTimeStamp() { val numberAccounts = 4; val numberContactsPerAccount = 3; val timeStamps = longArrayOf(100000000, 200000000, 300000000, 400000000); val timeStampStrs = Array(4) { Constants.TIMESTAMP_FORMAT.format(Date(timeStamps[it])) }; val accounts = Array(numberAccounts) { JSONObject() }; val mapAccountContacts = HashMap<JSONObject, Array<JSONObject>>(); for (i in 0 until numberAccounts) { val account = JSONObject(); account.put(Constants.ID, SyncTarget.createLocalId()); account.put("AccountTimeStamp1", timeStampStrs[i % timeStampStrs.size]); account.put("AccountTimeStamp2", timeStampStrs[0]); val contacts = Array(numberContactsPerAccount) { j -> JSONObject().apply { put(Constants.ID, SyncTarget.createLocalId()); put(ACCOUNT_ID, account.get(Constants.ID)); put("ContactTimeStamp1", timeStampStrs[1]); put("ContactTimeStamp2", timeStampStrs[j % timeStampStrs.size]) } }; mapAccountContacts[account] = contacts; accounts[i] = account }; val records = JSONArray(); for (account in accounts) { val record = JSONObject(account.toString()); val contacts = JSONArray(); for (contact in mapAccountContacts[account]!!) { contacts.put(contact) }; record.put("Contacts", contacts); records.put(record) }; Assert.assertEquals(timeStamps[3], getAccountContactsSyncDownTarget("AccountTimeStamp1", "ContactTimeStamp1", null).getLatestModificationTimeStamp(records)); Assert.assertEquals(timeStamps[3], getAccountContactsSyncDownTarget("AccountTimeStamp1", "ContactTimeStamp2", null).getLatestModificationTimeStamp(records)); Assert.assertEquals(timeStamps[1], getAccountContactsSyncDownTarget("AccountTimeStamp2", "ContactTimeStamp1", null).getLatestModificationTimeStamp(records)); Assert.assertEquals(timeStamps[2], getAccountContactsSyncDownTarget("AccountTimeStamp2", "ContactTimeStamp2", null).getLatestModificationTimeStamp(records)) }

    @Test fun testSyncDown() { createAccountsAndContactsOnServer(4, 3); val target = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdToFields!!.keys))); trySyncDown(SyncState.MergeMode.OVERWRITE, target, ACCOUNTS_SOUP, 4, 1); checkDb(accountIdToFields!!, ACCOUNTS_SOUP); for (accountId in accountIdToFields!!.keys) { checkDb(accountIdContactIdToFields!![accountId]!!, CONTACTS_SOUP) } }
    @Test fun testSyncDownNoChildren() { accountIdToFields = createRecordsOnServerReturnFields(4, Constants.ACCOUNT, null); val target = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdToFields!!.keys))); trySyncDown(SyncState.MergeMode.OVERWRITE, target, ACCOUNTS_SOUP, 4, 1); checkDb(accountIdToFields!!, ACCOUNTS_SOUP) }

    @Test fun testSyncDownWithoutOverwrite() { createAccountsAndContactsOnServer(4, 3); val target = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdToFields!!.keys))); trySyncDown(SyncState.MergeMode.OVERWRITE, target, ACCOUNTS_SOUP, 4, 1); val accountIds = accountIdToFields!!.keys.toTypedArray(); val accountIdUpdated = accountIds[0]; val accountIdToFieldsUpdated = makeLocalChanges(accountIdToFields!!, ACCOUNTS_SOUP, arrayOf(accountIdUpdated)); val contactIdToFieldsUpdated = makeLocalChanges(accountIdContactIdToFields!![accountIdUpdated]!!, CONTACTS_SOUP); val otherAccountId = accountIds[1]; val otherContactIdToFieldsUpdated = makeLocalChanges(accountIdContactIdToFields!![otherAccountId]!!, CONTACTS_SOUP); trySyncDown(SyncState.MergeMode.LEAVE_IF_CHANGED, target, ACCOUNTS_SOUP, 4, 1); val accountIdToFieldsExpected = HashMap(accountIdToFields!!); accountIdToFieldsExpected.putAll(accountIdToFieldsUpdated); checkDb(accountIdToFieldsExpected, ACCOUNTS_SOUP); for (accountId in accountIdToFields!!.keys) { if (accountId == accountIdUpdated) { checkDbStateFlags(listOf(accountId), false, true, false, ACCOUNTS_SOUP); checkDb(contactIdToFieldsUpdated, CONTACTS_SOUP); checkDbStateFlags(contactIdToFieldsUpdated.keys, false, true, false, CONTACTS_SOUP) } else if (accountId == otherAccountId) { checkDbStateFlags(listOf(accountId), false, false, false, ACCOUNTS_SOUP); checkDb(otherContactIdToFieldsUpdated, CONTACTS_SOUP); checkDbStateFlags(otherContactIdToFieldsUpdated.keys, false, true, false, CONTACTS_SOUP) } else { checkDbStateFlags(listOf(accountId), false, false, false, ACCOUNTS_SOUP); checkDb(accountIdContactIdToFields!![accountId]!!, CONTACTS_SOUP); checkDbStateFlags(accountIdContactIdToFields!![accountId]!!.keys, false, false, false, CONTACTS_SOUP) } }; trySyncDown(SyncState.MergeMode.OVERWRITE, target, ACCOUNTS_SOUP, 4, 1); checkDb(accountIdToFields!!, ACCOUNTS_SOUP); checkDbStateFlags(accountIdToFields!!.keys, false, false, false, ACCOUNTS_SOUP); for (accountId in accountIdToFields!!.keys) { checkDb(accountIdContactIdToFields!![accountId]!!, CONTACTS_SOUP); checkDbStateFlags(accountIdContactIdToFields!![accountId]!!.keys, false, false, false, CONTACTS_SOUP) } }

    @Test fun testReSyncWithUpdatedParents() { createAccountsAndContactsOnServer(4, 3); val target = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdToFields!!.keys))); val syncId = trySyncDown(SyncState.MergeMode.OVERWRITE, target, ACCOUNTS_SOUP, 4, 1); val sync = syncManager.getSyncStatus(syncId)!!; val options = sync.options; val maxTimeStamp = sync.maxTimeStamp; Assert.assertTrue("Wrong time stamp", maxTimeStamp > 0); val idToFieldsUpdated = makeRemoteChanges(accountIdToFields!!, Constants.ACCOUNT); val queue = SyncUpdateCallbackQueue(syncId); syncManager.reSync(syncId, queue); checkStatus(queue.getNextSyncUpdate(syncId), SyncState.Type.syncDown, syncId, target, options, SyncState.Status.RUNNING, 0, -1); checkStatus(queue.getNextSyncUpdate(syncId), SyncState.Type.syncDown, syncId, target, options, SyncState.Status.RUNNING, 0, idToFieldsUpdated.size); checkStatus(queue.getNextSyncUpdate(syncId), SyncState.Type.syncDown, syncId, target, options, SyncState.Status.DONE, 100, idToFieldsUpdated.size); checkDb(idToFieldsUpdated, ACCOUNTS_SOUP); Assert.assertTrue("Wrong time stamp", syncManager.getSyncStatus(syncId)!!.maxTimeStamp > maxTimeStamp) }

    @Test fun testReSyncWithUpdatedChildren() { createAccountsAndContactsOnServer(4, 3); val target = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdToFields!!.keys))); val syncId = trySyncDown(SyncState.MergeMode.OVERWRITE, target, ACCOUNTS_SOUP, 4, 1); val sync = syncManager.getSyncStatus(syncId)!!; val options = sync.options; val maxTimeStamp = sync.maxTimeStamp; Assert.assertTrue("Wrong time stamp", maxTimeStamp > 0); val accountIds = accountIdToFields!!.keys.toTypedArray(); val accountId = accountIds[0]; val accountIdToFieldsUpdated = makeRemoteChanges(accountIdToFields!!, Constants.ACCOUNT, arrayOf(accountId)); val contactIdToFieldsUpdated = makeRemoteChanges(accountIdContactIdToFields!![accountId]!!, Constants.CONTACT); val otherAccountId = accountIds[1]; val otherContactIdToFieldsUpdated = makeRemoteChanges(accountIdContactIdToFields!![otherAccountId]!!, Constants.CONTACT); val queue = SyncUpdateCallbackQueue(syncId); syncManager.reSync(syncId, queue); checkStatus(queue.getNextSyncUpdate(syncId), SyncState.Type.syncDown, syncId, target, options, SyncState.Status.RUNNING, 0, -1); checkStatus(queue.getNextSyncUpdate(syncId), SyncState.Type.syncDown, syncId, target, options, SyncState.Status.RUNNING, 0, 1); checkStatus(queue.getNextSyncUpdate(syncId), SyncState.Type.syncDown, syncId, target, options, SyncState.Status.DONE, 100, 1); checkDb(accountIdToFieldsUpdated, ACCOUNTS_SOUP); checkDb(contactIdToFieldsUpdated, CONTACTS_SOUP); checkDb(accountIdContactIdToFields!![otherAccountId]!!, CONTACTS_SOUP); Assert.assertTrue("Wrong time stamp", syncManager.getSyncStatus(syncId)!!.maxTimeStamp > maxTimeStamp) }

    @Test fun testCleanResyncGhostsForParentChildrenTarget() { createAccountsAndContactsOnServer(4, 3); val target = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdToFields!!.keys))); val syncId = trySyncDown(SyncState.MergeMode.OVERWRITE, target, ACCOUNTS_SOUP, 4, 1); val accountIdDeleted = accountIdToFields!!.keys.toTypedArray()[0]; deleteRecordsByIdOnServer(HashSet(listOf(accountIdDeleted)), Constants.ACCOUNT); tryCleanResyncGhosts(syncId); val accountIdToFieldsLeft = HashMap(accountIdToFields!!); accountIdToFieldsLeft.remove(accountIdDeleted); checkDb(accountIdToFieldsLeft, ACCOUNTS_SOUP); checkDbDeleted(ACCOUNTS_SOUP, arrayOf(accountIdDeleted), Constants.ID); for (accountId in accountIdContactIdToFields!!.keys) { if (accountId == accountIdDeleted) { checkDbDeleted(CONTACTS_SOUP, accountIdContactIdToFields!![accountId]!!.keys.toTypedArray(), Constants.ID) } else { checkDb(accountIdContactIdToFields!![accountId]!!, CONTACTS_SOUP) } } }

    @Test fun testCleanResyncGhostsForParentChildrenWithMultipleSyncs() { createAccountsAndContactsOnServer(6, 3); val accountIds = accountIdToFields!!.keys.toTypedArray(); val accountIdsFirstSubset = accountIds.copyOfRange(0, 3); val accountIdsSecondSubset = accountIds.copyOfRange(2, 6); val firstTarget = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdsFirstSubset.toList()))); val firstSyncId = trySyncDown(SyncState.MergeMode.OVERWRITE, firstTarget, ACCOUNTS_SOUP, accountIdsFirstSubset.size, 1); checkDbExist(ACCOUNTS_SOUP, accountIdsFirstSubset, Constants.ID); checkDbSyncIdField(accountIdsFirstSubset, firstSyncId, ACCOUNTS_SOUP); val secondTarget = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdsSecondSubset.toList()))); val secondSyncId = trySyncDown(SyncState.MergeMode.OVERWRITE, secondTarget, ACCOUNTS_SOUP, accountIdsSecondSubset.size, 1); checkDbExist(ACCOUNTS_SOUP, accountIdsSecondSubset, Constants.ID); checkDbSyncIdField(accountIdsSecondSubset, secondSyncId, ACCOUNTS_SOUP); deleteRecordsByIdOnServer(HashSet(listOf(accountIds[0], accountIds[2], accountIds[5])), Constants.ACCOUNT); tryCleanResyncGhosts(firstSyncId); checkDbExist(ACCOUNTS_SOUP, arrayOf(accountIds[1], accountIds[2], accountIds[3], accountIds[4], accountIds[5]), Constants.ID); checkDbDeleted(ACCOUNTS_SOUP, arrayOf(accountIds[0]), Constants.ID); tryCleanResyncGhosts(secondSyncId); checkDbExist(ACCOUNTS_SOUP, arrayOf(accountIds[1], accountIds[3], accountIds[4]), Constants.ID); checkDbDeleted(ACCOUNTS_SOUP, arrayOf(accountIds[2], accountIds[5]), Constants.ID) }

