    @Test fun testSyncUpWithLocallyCreatedParentRecords() { val contactIdToName = createRecordsOnServer(6, Constants.CONTACT); val contactSyncDownTarget = SoqlSyncDownTarget("SELECT Id, LastName, LastModifiedDate FROM Contact WHERE Id IN ${makeInClause(contactIdToName.keys)}"); trySyncDown(SyncState.MergeMode.OVERWRITE, contactSyncDownTarget, CONTACTS_SOUP, contactIdToName.size, 1); val accountNames = arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)); val localAccounts = createAccountsLocally(accountNames); val accountNameToServerId = HashMap<String, String>(); for (localAccount in localAccounts) { accountNameToServerId[localAccount.getString(Constants.NAME)] = localAccount.getString(Constants.ID) }; val contactIdToAccountName = HashMap<String, String>(); val idToFieldsLocallyUpdated = HashMap<String, Map<String, Any>>(); var i = 0; for (contactId in contactIdToName.keys) { val fieldsLocallyUpdated = HashMap<String, Any>(); val accountName = accountNames[i % accountNames.size]; fieldsLocallyUpdated[ACCOUNT_ID] = accountNameToServerId[accountName]!!; idToFieldsLocallyUpdated[contactId] = fieldsLocallyUpdated; contactIdToAccountName[contactId] = accountName; i++ }; updateRecordsLocally(idToFieldsLocallyUpdated, CONTACTS_SOUP); val target = getAccountContactsSyncUpTarget(); trySyncUp(target, accountNames.size, SyncState.MergeMode.OVERWRITE); val accountIdToFieldsCreated = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, accountNames); checkDbStateFlags(accountIdToFieldsCreated.keys, false, false, false, ACCOUNTS_SOUP); for (accountId in accountIdToFieldsCreated.keys) { accountNameToServerId[accountIdToFieldsCreated[accountId]!![Constants.NAME] as String] = accountId }; checkServer(accountIdToFieldsCreated, Constants.ACCOUNT); val contactIdToFieldsUpdated = getIdToFieldsByName(CONTACTS_SOUP, arrayOf(Constants.LAST_NAME, ACCOUNT_ID), Constants.LAST_NAME, contactIdToName.values.toTypedArray()); checkDbStateFlags(contactIdToFieldsUpdated.keys, false, false, false, CONTACTS_SOUP); for (contactId in contactIdToFieldsUpdated.keys) { Assert.assertEquals("Wrong accountId", accountNameToServerId[contactIdToAccountName[contactId]], contactIdToFieldsUpdated[contactId]!![ACCOUNT_ID]) }; checkServer(contactIdToFieldsUpdated, Constants.CONTACT); deleteRecordsByIdOnServer(accountIdToFieldsCreated.keys, Constants.ACCOUNT); deleteRecordsByIdOnServer(contactIdToFieldsUpdated.keys, Constants.CONTACT) }

    @Test fun testSyncUpWithLocallyCreatedChildrenRecords() { val accountIdToName = createRecordsOnServer(2, Constants.ACCOUNT); val accountNames = accountIdToName.values.toTypedArray(); val accountSyncDownTarget = SoqlSyncDownTarget("SELECT Id, Name, LastModifiedDate FROM Account WHERE Id IN ${makeInClause(accountIdToName.keys)}"); trySyncDown(SyncState.MergeMode.OVERWRITE, accountSyncDownTarget, ACCOUNTS_SOUP, accountIdToName.size, 1); val accountIdToFieldsCreated = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME), Constants.NAME, accountNames); val contactsForAccountsLocally = createContactsForAccountsLocally(3, *accountIdToFieldsCreated.keys.toTypedArray()); val contactNamesList = ArrayList<String>(); for (contacts in contactsForAccountsLocally.values) { for (contact in contacts) { contactNamesList.add(contact.getString(Constants.LAST_NAME)) } }; val contactNames = contactNamesList.toTypedArray(); val target = getAccountContactsSyncUpTarget(); trySyncUp(target, accountNames.size, SyncState.MergeMode.OVERWRITE); val contactIdToFieldsCreated = getIdToFieldsByName(CONTACTS_SOUP, arrayOf(Constants.LAST_NAME, ACCOUNT_ID), Constants.LAST_NAME, contactNames); checkDbStateFlags(contactIdToFieldsCreated.keys, false, false, false, CONTACTS_SOUP); checkServer(contactIdToFieldsCreated, Constants.CONTACT); deleteRecordsByIdOnServer(accountIdToFieldsCreated.keys, Constants.ACCOUNT); deleteRecordsByIdOnServer(contactIdToFieldsCreated.keys, Constants.CONTACT) }

    @Test fun testSyncUpWithLocallyCreatedChildrenRemotelyDeletedParent() { val accountIdToName = createRecordsOnServer(1, Constants.ACCOUNT); val accountId = accountIdToName.keys.toTypedArray()[0]; val accountName = accountIdToName.values.toTypedArray()[0]; val accountSyncDownTarget = SoqlSyncDownTarget("SELECT Id, Name, LastModifiedDate FROM Account WHERE Id = '$accountId'"); trySyncDown(SyncState.MergeMode.OVERWRITE, accountSyncDownTarget, ACCOUNTS_SOUP, accountIdToName.size, 1); val contactsForAccountsLocally = createContactsForAccountsLocally(3, accountId); val contactNamesList = ArrayList<String>(); for (contacts in contactsForAccountsLocally.values) { for (contact in contacts) { contactNamesList.add(contact.getString(Constants.LAST_NAME)) } }; val contactNames = contactNamesList.toTypedArray(); deleteRecordsByIdOnServer(HashSet(listOf(accountId)), Constants.ACCOUNT); val target = getAccountContactsSyncUpTarget(); trySyncUp(target, 1, SyncState.MergeMode.OVERWRITE); val accountFields = HashMap<String, Any>(); accountFields[Constants.NAME] = accountName; val newAccountId = checkRecordRecreated(accountId, accountFields, Constants.NAME, ACCOUNTS_SOUP, Constants.ACCOUNT, null, null); val contactIdToFieldsCreated = getIdToFieldsByName(CONTACTS_SOUP, arrayOf(Constants.LAST_NAME, ACCOUNT_ID), Constants.LAST_NAME, contactNames); checkDbStateFlags(contactIdToFieldsCreated.keys, false, false, false, CONTACTS_SOUP); checkServer(contactIdToFieldsCreated, Constants.CONTACT); for (cid in contactIdToFieldsCreated.keys) { Assert.assertEquals("Wrong accountId", newAccountId, contactIdToFieldsCreated[cid]!![ACCOUNT_ID]) }; deleteRecordsByIdOnServer(HashSet(listOf(newAccountId)), Constants.ACCOUNT); deleteRecordsByIdOnServer(contactIdToFieldsCreated.keys, Constants.CONTACT) }

    @Test fun testSyncUpWithErrors() { createAccountsAndContactsOnServer(3, 3); val syncDownTarget = getAccountContactsSyncDownTarget(String.format("%s IN %s", Constants.ID, makeInClause(accountIdToFields!!.keys))); trySyncDown(SyncState.MergeMode.OVERWRITE, syncDownTarget, ACCOUNTS_SOUP, 3, 1); val accountIds = accountIdToFields!!.keys.toTypedArray(); val account1Id = accountIds[0]; val contactIdsOfAccount1 = accountIdContactIdToFields!![account1Id]!!.keys.toTypedArray(); val contact11Id = contactIdsOfAccount1[0]; val contact12Id = contactIdsOfAccount1[1]; val account2Id = accountIds[1]; val contactIdsOfAccount2 = accountIdContactIdToFields!![account2Id]!!.keys.toTypedArray(); val contact21Id = contactIdsOfAccount2[0]; val contact22Id = contactIdsOfAccount2[1]; val buffer = StringBuilder(255); for (i in 0 until 255) buffer.append("x"); val suffixTooLong = buffer.toString(); val updatedAccount1Fields = updateRecordLocally(ACCOUNTS_SOUP, account1Id, accountIdToFields!![account1Id]!!)[account1Id]!!; val updatedContact11Fields = updateRecordLocally(CONTACTS_SOUP, contact11Id, accountIdContactIdToFields!![account1Id]!![contact11Id]!!)[contact11Id]!!; val updatedContact21Fields = updateRecordLocally(CONTACTS_SOUP, contact21Id, accountIdContactIdToFields!![account2Id]!![contact21Id]!!)[contact21Id]!!; updateRecordLocally(ACCOUNTS_SOUP, account2Id, accountIdToFields!![account2Id]!!, suffixTooLong); updateRecordLocally(CONTACTS_SOUP, contact12Id, accountIdContactIdToFields!![account1Id]!![contact12Id]!!, suffixTooLong); updateRecordLocally(CONTACTS_SOUP, contact22Id, accountIdContactIdToFields!![account2Id]!![contact22Id]!!, suffixTooLong); trySyncUp(getAccountContactsSyncUpTarget(), 2, SyncState.MergeMode.OVERWRITE); checkDbStateFlags(listOf(account1Id), false, false, false, ACCOUNTS_SOUP); checkDbStateFlags(listOf(contact11Id, contact21Id), false, false, false, CONTACTS_SOUP); checkDbStateFlags(listOf(account2Id), false, true, false, ACCOUNTS_SOUP); checkDbStateFlags(listOf(contact12Id, contact22Id), false, true, false, CONTACTS_SOUP); checkDbLastErrorField(arrayOf(account2Id), "Account Name: data value too large", ACCOUNTS_SOUP); checkDbLastErrorField(arrayOf(contact12Id, contact22Id), "Last Name: data value too large", CONTACTS_SOUP) }

    @Test fun testParentChildrenSyncUpWithExternalId() { val externalIdFieldName = "Id"; createAccountsAndContactsOnServer(3, 1); val accountIds = accountIdToFields!!.keys.toTypedArray(); Arrays.sort(accountIds); val accountId0 = accountIds[0]; val accountId1 = accountIds[1]; val accountId2 = accountIds[2]; val originalAccountName2 = accountIdToFields!![accountId2]!![Constants.NAME] as String; val contactId0 = accountIdContactIdToFields!![accountId0]!!.keys.toTypedArray()[0]; val contactId1 = accountIdContactIdToFields!![accountId1]!!.keys.toTypedArray()[0]; val contactId2 = accountIdContactIdToFields!![accountId2]!!.keys.toTypedArray()[0]; val originalContactName0 = accountIdContactIdToFields!![accountId0]!![contactId0]!![Constants.LAST_NAME] as String; val accountToContactMap = createAccountsAndContactsLocally(arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)), 1); val localAccounts = accountToContactMap.keys.toTypedArray(); val localContacts = arrayOf(accountToContactMap[localAccounts[0]]!![0], accountToContactMap[localAccounts[1]]!![0], accountToContactMap[localAccounts[2]]!![0]); val accountName0 = localAccounts[0].getString(Constants.NAME); val accountName1 = localAccounts[1].getString(Constants.NAME); val accountName2 = localAccounts[2].getString(Constants.NAME); val contactName0 = localContacts[0].getString(Constants.LAST_NAME); val contactName1 = localContacts[1].getString(Constants.LAST_NAME); val contactName2 = localContacts[2].getString(Constants.LAST_NAME); localAccounts[0].put(externalIdFieldName, accountId0); smartStore.upsert(ACCOUNTS_SOUP, localAccounts[0]); localAccounts[1].put(externalIdFieldName, accountId1); smartStore.upsert(ACCOUNTS_SOUP, localAccounts[1]); localContacts[0].put(ACCOUNT_ID, accountId0); smartStore.upsert(CONTACTS_SOUP, localContacts[0]); localContacts[1].put(externalIdFieldName, contactId1); localContacts[1].put(ACCOUNT_ID, accountId1); smartStore.upsert(CONTACTS_SOUP, localContacts[1]); localContacts[2].put(externalIdFieldName, contactId2); smartStore.upsert(CONTACTS_SOUP, localContacts[2]); trySyncUp(getAccountContactsSyncUpTarget(Constants.LAST_MODIFIED_DATE, Constants.LAST_MODIFIED_DATE, externalIdFieldName, externalIdFieldName), 3, SyncState.MergeMode.OVERWRITE); val newAccountId = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(), Constants.NAME, arrayOf(accountName2)).keys.toTypedArray()[0]; val newContactId = getIdToFieldsByName(CONTACTS_SOUP, arrayOf(), Constants.LAST_NAME, arrayOf(contactName0)).keys.toTypedArray()[0]; val expectedAccountsDbIdToFields = HashMap<String, Map<String, Any>>(); expectedAccountsDbIdToFields[accountId0] = createFieldsMap(Constants.NAME, accountName0); expectedAccountsDbIdToFields[accountId1] = createFieldsMap(Constants.NAME, accountName1); expectedAccountsDbIdToFields[newAccountId] = createFieldsMap(Constants.NAME, accountName2); checkDbStateFlags(expectedAccountsDbIdToFields.keys, false, false, false, ACCOUNTS_SOUP); checkDb(expectedAccountsDbIdToFields, ACCOUNTS_SOUP); val expectedContactsDbIdToFields = HashMap<String, Map<String, Any>>(); expectedContactsDbIdToFields[newContactId] = createFieldsMap(Constants.LAST_NAME, contactName0); expectedContactsDbIdToFields[contactId1] = createFieldsMap(Constants.LAST_NAME, contactName1); expectedContactsDbIdToFields[contactId2] = createFieldsMap(Constants.LAST_NAME, contactName2); checkDbStateFlags(expectedContactsDbIdToFields.keys, false, false, false, CONTACTS_SOUP); checkDb(expectedContactsDbIdToFields, CONTACTS_SOUP); deleteRecordsByIdOnServer(Collections.singletonList(newAccountId), Constants.ACCOUNT); deleteRecordsByIdOnServer(Collections.singletonList(newContactId), Constants.CONTACT) }
